void main(String[] args) {
    String file = null;
    String since = null;
    String level = null;
    int top = 5;

    for (int i = 0; i < args.length; i++) {
        String a = args[i];
        switch (a) {
            case "--help" -> {
                printHelp();
                return;
            }
            case "--since" -> {
                if (i + 1 >= args.length) usageError("missing value for --since");
                since = args[++i];
            }
            case "--level" -> {
                if (i + 1 >= args.length) usageError("missing value for --level");
                level = args[++i];
            }
            case "--top" -> {
                if (i + 1 >= args.length) usageError("missing value for --top");
                String v = args[++i];
                try {
                    top = Integer.parseInt(v);
                } catch (NumberFormatException e) {
                    error("invalid value for --top: " + v);
                }
            }
            default -> {
                if (a.startsWith("--")) {
                    System.err.println("unknown flag: " + a);
                    System.exit(2);
                } else if (file != null) {
                    usageError("unexpected argument: " + a);
                } else {
                    file = a;
                }
            }
        }
    }

    if (level != null && !isValidLevel(level)) {
        error("invalid value for --level: " + level);
    }
    if (since != null && !isValidTimestamp(since)) {
        error("invalid value for --since: " + since);
    }

    long total = 0;
    long debugCount = 0, infoCount = 0, warnCount = 0, errorCount = 0;
    String first = null;
    String last = null;

    Map<String, Integer> groupCounts = new HashMap<>();
    Map<String, String> groupFirstMessage = new HashMap<>();

    try (BufferedReader reader = openReader(file)) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(" ", 3);
            if (parts.length < 3) continue;
            String ts = parts[0];
            String lvl = parts[1];
            String message = parts[2];

            if (!isValidTimestamp(ts)) continue;
            if (!isValidLevel(lvl)) continue;

            if (since != null && ts.compareTo(since) < 0) continue;
            if (level != null && !lvl.equals(level)) continue;

            total++;
            switch (lvl) {
                case "DEBUG" -> debugCount++;
                case "INFO" -> infoCount++;
                case "WARN" -> warnCount++;
                case "ERROR" -> errorCount++;
            }
            if (first == null) first = ts;
            last = ts;

            if (lvl.equals("ERROR")) {
                String normalized = normalize(message);
                groupCounts.merge(normalized, 1, Integer::sum);
                groupFirstMessage.putIfAbsent(normalized, message);
            }
        }
    } catch (IOException e) {
        error("cannot read " + file);
    }

    IO.println("total: " + total);
    IO.println("by level: DEBUG=" + debugCount + " INFO=" + infoCount + " WARN=" + warnCount + " ERROR=" + errorCount);
    IO.println("first: " + (first == null ? "n/a" : first));
    IO.println("last: " + (last == null ? "n/a" : last));
    IO.println("top errors:");

    List<String> keys = new ArrayList<>(groupCounts.keySet());
    keys.sort((k1, k2) -> {
        int c1 = groupCounts.get(k1);
        int c2 = groupCounts.get(k2);
        if (c1 != c2) return Integer.compare(c2, c1);
        return groupFirstMessage.get(k1).compareTo(groupFirstMessage.get(k2));
    });

    for (int i = 0; i < keys.size() && i < top; i++) {
        String key = keys.get(i);
        IO.println("  " + groupCounts.get(key) + " " + groupFirstMessage.get(key));
    }
}

BufferedReader openReader(String file) throws IOException {
    if (file == null || file.equals("-")) {
        return new BufferedReader(new InputStreamReader(System.in, StandardCharsets.UTF_8));
    }
    return Files.newBufferedReader(Path.of(file), StandardCharsets.UTF_8);
}

boolean isValidLevel(String s) {
    return switch (s) {
        case "DEBUG", "INFO", "WARN", "ERROR" -> true;
        default -> false;
    };
}

final DateTimeFormatter TIMESTAMP_FORMAT = DateTimeFormatter
        .ofPattern("uuuu-MM-dd'T'HH:mm:ss")
        .withResolverStyle(ResolverStyle.STRICT);

boolean isValidTimestamp(String s) {
    if (s.length() != 19) return false;
    try {
        LocalDateTime.parse(s, TIMESTAMP_FORMAT);
        return true;
    } catch (DateTimeParseException e) {
        return false;
    }
}

final Pattern UUID_PATTERN = Pattern.compile(
        "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}");
final Pattern HEX_PATTERN = Pattern.compile(
        "\\b(?=[0-9a-fA-F]*[a-fA-F])[0-9a-fA-F]{6,}\\b");
final Pattern DIGIT_PATTERN = Pattern.compile("[0-9]+");

String normalize(String message) {
    String result = UUID_PATTERN.matcher(message).replaceAll("<uuid>");
    result = HEX_PATTERN.matcher(result).replaceAll("<hex>");
    result = DIGIT_PATTERN.matcher(result).replaceAll("<num>");
    return result;
}

void printHelp() {
    IO.println("Usage: logsum [FILE] [--since TIMESTAMP] [--level LEVEL] [--top N]");
    IO.println("");
    IO.println("Arguments:");
    IO.println("  FILE               Log file to read (default: stdin, or use -)");
    IO.println("");
    IO.println("Options:");
    IO.println("  --since TIMESTAMP  Only include lines with timestamp >= TIMESTAMP (YYYY-MM-DDTHH:MM:SS)");
    IO.println("  --level LEVEL      Only include lines at exactly this level (DEBUG, INFO, WARN, ERROR)");
    IO.println("  --top N            Number of top error groups to show (default: 5)");
    IO.println("  --help             Show this help message");
}

void usageError(String message) {
    System.err.println("error: " + message);
    System.exit(2);
}

void error(String message) {
    System.err.println("error: " + message);
    System.exit(2);
}

